class TestExitGracefulWorkerHandoff:
    """Verify `exit()` defers teardown for an in-flight agent worker."""

    @pytest.fixture(autouse=True)
    def _reset_background_hooks(self) -> Iterator[None]:
        """Isolate the module-global hook task set across tests.

        These tests read the real `has_pending_hooks()`; a stray undone task
        left in `_background_tasks` by an earlier test would otherwise push
        `test_synchronous_when_worker_finished` onto the graceful path and flake.
        """
        import deepagents_code.hooks as hooks_mod

        hooks_mod._background_tasks.clear()
        yield
        hooks_mod._background_tasks.clear()

    async def test_timeout_does_not_cancel_worker_wait(self) -> None:
        """A timed-out graceful exit must not abort worker cleanup."""
        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            wait_started = asyncio.Event()
            wait_done = asyncio.Event()
            wait_future: asyncio.Future[None] = asyncio.Future()
            wait_cancelled = False

            async def wait_worker() -> None:
                nonlocal wait_cancelled
                wait_started.set()
                try:
                    await wait_future
                except asyncio.CancelledError:
                    wait_cancelled = True
                    raise
                finally:
                    wait_done.set()

            app._agent_running = True
            worker = MagicMock()
            worker.is_finished = False
            worker.wait = AsyncMock(side_effect=wait_worker)
            app._agent_worker = worker

            with (
                patch("deepagents_code.app._GRACEFUL_EXIT_WAIT_SECONDS", 0.01),
                patch.object(App, "exit") as super_exit,
            ):
                app.exit()
                assert app._graceful_exit_task is not None
                await wait_started.wait()
                await app._graceful_exit_task

                super_exit.assert_called_once()

            assert not wait_cancelled
            assert not wait_future.cancelled()

            wait_future.set_result(None)
            await asyncio.wait_for(wait_done.wait(), timeout=1.0)
            worker.wait.assert_awaited_once()

    @pytest.mark.parametrize(
        ("error_key", "expected_level", "expected_substring"),
        [
            ("worker_failed", logging.WARNING, "did not finish persisting"),
            ("unexpected", logging.WARNING, "raised unexpectedly"),
            ("worker_cancelled", logging.DEBUG, "cancelled cleanly"),
        ],
    )
    async def test_graceful_exit_always_tears_down(
        self,
        error_key: str,
        expected_level: int,
        expected_substring: str,
        caplog: pytest.LogCaptureFixture,
    ) -> None:
        """Every exception path through `_graceful_exit` still tears down.

        The `finally` block runs `super().exit()` on all branches (the only
        call that stops the event loop), and each branch logs at the
        documented level.
        """
        from textual.worker import WorkerCancelled, WorkerFailed

        errors: dict[str, BaseException] = {
            "worker_failed": WorkerFailed(ValueError("boom")),
            "unexpected": RuntimeError("boom"),
            "worker_cancelled": WorkerCancelled("cancelled"),
        }

        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            app._agent_running = True
            worker = MagicMock()
            worker.is_finished = False
            worker.wait = AsyncMock(side_effect=errors[error_key])
            app._agent_worker = worker

            with (
                caplog.at_level(logging.DEBUG, logger="deepagents_code.app"),
                patch.object(App, "exit") as super_exit,
            ):
                app.exit()
                assert app._graceful_exit_task is not None
                await app._graceful_exit_task
                # The finally block tears down on every exception path.
                super_exit.assert_called_once()

        matching = [
            record
            for record in caplog.records
            if record.levelno == expected_level and expected_substring in record.message
        ]
        assert matching, (
            f"expected a {logging.getLevelName(expected_level)} log containing "
            f"{expected_substring!r}"
        )

    async def test_synchronous_when_worker_finished(self) -> None:
        """A finished worker tears down synchronously with no deferred task."""
        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            app._agent_running = True
            worker = MagicMock()
            worker.is_finished = True
            worker.wait = AsyncMock()
            app._agent_worker = worker

            with patch.object(App, "exit") as super_exit:
                app.exit()
                super_exit.assert_called_once()
            assert app._graceful_exit_task is None
            worker.wait.assert_not_awaited()

    async def test_synchronous_when_agent_not_running(self) -> None:
        """An idle session tears down synchronously even with a worker set."""
        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            app._agent_running = False
            worker = MagicMock()
            worker.is_finished = False
            worker.wait = AsyncMock()
            app._agent_worker = worker

            with patch.object(App, "exit") as super_exit:
                app.exit()
                super_exit.assert_called_once()
            assert app._graceful_exit_task is None
            worker.wait.assert_not_awaited()

    async def test_hook_drain_timeout_is_bounded_and_logged(
        self, caplog: pytest.LogCaptureFixture
    ) -> None:
        """A hung hook drain is bounded by the graceful-exit budget and logged.

        A slow/hanging hook subprocess must not stall an interactive quit; the
        drain is wrapped in `asyncio.wait_for`, so teardown proceeds after the
        timeout and the possibly-dropped final tool.result is announced rather
        than the UI silently hanging.
        """

        async def hang() -> None:
            await asyncio.Event().wait()

        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()

            with (
                caplog.at_level(logging.WARNING, logger="deepagents_code.app"),
                patch("deepagents_code.hooks.has_pending_hooks", return_value=True),
                patch("deepagents_code.hooks.drain_pending_hooks", new=hang),
                patch("deepagents_code.app._GRACEFUL_EXIT_WAIT_SECONDS", 0.01),
                patch.object(App, "exit") as super_exit,
            ):
                app.exit()
                assert app._graceful_exit_task is not None
                await app._graceful_exit_task

            super_exit.assert_called_once()

        assert any(
            "Hook drain did not finish" in record.message
            and record.levelno == logging.WARNING
            for record in caplog.records
        )

    async def test_client_session_end_timeout_is_bounded_and_at_most_once(
        self,
        caplog: pytest.LogCaptureFixture,
    ) -> None:
        """A slow Hooks v2 `SessionEnd` cannot stall or fire twice on TUI exit."""
        from deepagents_code.approval_mode import ApprovalMode
        from deepagents_code.hooks.manager import HookSessionIdentity
        from deepagents_code.hooks.models.domain import (
            HookEvent,
            SessionEndDecision,
        )

        calls = 0
        cancelled = asyncio.Event()
        drain_observed_cancellation = asyncio.Event()

        async def invoke(_invocation: object) -> SessionEndDecision:
            nonlocal calls
            calls += 1
            try:
                await asyncio.sleep(60)
            except asyncio.CancelledError:
                cancelled.set()
                raise
            return SessionEndDecision(event=HookEvent.SESSION_END)

        async def drain_pending() -> None:
            try:
                await asyncio.wait_for(cancelled.wait(), timeout=0.1)
            except TimeoutError:
                return
            drain_observed_cancellation.set()

        runtime = MagicMock()
        runtime.cwd = Path.cwd()
        runtime.configured_events.return_value = frozenset({HookEvent.SESSION_END})
        runtime.invoke = invoke
        hooks = HooksManager.adopting(
            runtime,
            identity=lambda: HookSessionIdentity(
                thread_id="t1",
                approval_mode=ApprovalMode.MANUAL,
            ),
        )
        app = DeepAgentsApp()
        loop = asyncio.get_running_loop()

        async with app.run_test() as pilot:
            await pilot.pause()
            if app._session_state is None:
                app._detached_hooks = hooks
            else:
                app._session_state.hooks = hooks

            with (
                caplog.at_level(logging.WARNING, logger="deepagents_code.app"),
                patch(
                    "deepagents_code.app.SESSION_END_DRAIN_TIMEOUT_SECONDS",
                    0.01,
                ),
                patch("deepagents_code.hooks.has_pending_hooks", return_value=True),
                patch("deepagents_code.hooks.drain_pending_hooks", new=drain_pending),
                patch.object(App, "exit") as super_exit,
            ):
                started = loop.time()
                app.exit()
                assert app._graceful_exit_task is not None
                await app._graceful_exit_task
                elapsed = loop.time() - started
                app.exit()

                assert super_exit.call_count == 2

        assert elapsed < 0.5
        assert cancelled.is_set()
        assert drain_observed_cancellation.is_set()
        assert calls == 1
        assert any(
            record.levelno == logging.WARNING
            and "SessionEnd hook drain did not finish" in record.message
            for record in caplog.records
        )

    async def test_second_exit_force_quits_pending_graceful_exit(self) -> None:
        """A second exit() during a pending graceful exit force-quits.

        Mashing Ctrl+D/Ctrl+C to bail out must not arm a second bounded wait;
        it should tear down immediately and leave the first task untouched.
        """
        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            app._agent_running = True
            worker = MagicMock()
            worker.is_finished = False
            worker.wait = AsyncMock()
            app._agent_worker = worker

            with patch.object(App, "exit") as super_exit:
                app.exit()
                pending = app._graceful_exit_task
                assert pending is not None
                super_exit.assert_not_called()

                # Second press before the loop runs the deferred task.
                app.exit()
                super_exit.assert_called_once()
                # The pending task is not re-armed or replaced.
                assert app._graceful_exit_task is pending
            pending.cancel()

    async def test_slow_session_end_does_not_block_agent_cleanup(self) -> None:
        """A slow `session.end` hook must not delay agent-cancellation cleanup.

        `session.end` is dispatched off the event loop at the very start of
        teardown, so the agent worker wait can start (and finish) while a slow
        hook is still running in its worker thread.
        """
        release = threading.Event()
        session_end_started = threading.Event()

        def blocking_session_end(*_args: object) -> None:
            session_end_started.set()
            release.wait(timeout=5.0)

        agent_wait_started = asyncio.Event()

        async def wait_worker() -> None:  # noqa: RUF029
            agent_wait_started.set()

        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            app._agent_running = True
            worker = MagicMock()
            worker.is_finished = False
            worker.wait = AsyncMock(side_effect=wait_worker)
            app._agent_worker = worker

            with (
                patch(
                    "deepagents_code.hooks._load_hooks",
                    return_value=[{"command": ["x"]}],
                ),
                patch(
                    "deepagents_code.hooks._dispatch_hook_sync",
                    side_effect=blocking_session_end,
                ),
                patch.object(App, "exit") as super_exit,
            ):
                app.exit()
                assert app._graceful_exit_task is not None

                # Agent cleanup runs even though session.end is still blocked.
                await asyncio.wait_for(agent_wait_started.wait(), timeout=1.0)
                # Bridge the cross-thread `threading.Event` into the loop with a
                # bounded wait (mirrors the force-quit sibling test) rather than
                # a busy-poll loop.
                assert await asyncio.wait_for(
                    asyncio.to_thread(session_end_started.wait, 2.0), timeout=3.0
                )
                # Teardown is still waiting on the blocked session.end hook.
                assert not app._graceful_exit_task.done()

                release.set()
                await asyncio.wait_for(app._graceful_exit_task, timeout=2.0)

            worker.wait.assert_awaited_once()
            super_exit.assert_called_once()

    async def test_server_shutdown_waits_for_agent_cleanup(self) -> None:
        """Server shutdown must not begin until agent persistence finishes.

        Interrupted-agent cleanup can cancel the remote run and persist partial
        state *through* the server, so stopping the server first would risk
        SIGTERM'ing it mid-request.
        """
        server_stopped = threading.Event()
        server_proc = MagicMock()
        server_proc.stop = MagicMock(side_effect=server_stopped.set)

        agent_release = asyncio.Event()
        agent_wait_started = asyncio.Event()

        async def wait_worker() -> None:
            agent_wait_started.set()
            await agent_release.wait()

        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()
            app._agent_running = True
            worker = MagicMock()
            worker.is_finished = False
            worker.wait = AsyncMock(side_effect=wait_worker)
            app._agent_worker = worker
            app._server_proc = server_proc

            with (
                # Large window so the agent-wait timeout cannot race the test.
                patch("deepagents_code.app._GRACEFUL_EXIT_WAIT_SECONDS", 30.0),
                patch.object(App, "exit") as super_exit,
            ):
                app.exit()
                assert app._graceful_exit_task is not None
                await asyncio.wait_for(agent_wait_started.wait(), timeout=1.0)

                # Structurally, server shutdown sits after the agent-wait block,
                # which is blocked here, so stop() cannot have run yet.
                assert not server_stopped.is_set()

                agent_release.set()
                await asyncio.wait_for(app._graceful_exit_task, timeout=2.0)

            assert server_stopped.is_set()
            server_proc.stop.assert_called_once_with()
            super_exit.assert_called_once()

    async def test_force_quit_can_drop_pending_session_end(self) -> None:
        """A force-quit second exit() can drop an in-flight `session.end`.

        Delivery is at-most-once: a normal exit awaits the off-loop dispatch in
        the teardown `finally`, but a force-quit second exit() runs the
        loop-stopping `super().exit()` immediately, while the dispatch is still
        in flight — which in production orphans it.
        """
        release = threading.Event()
        dispatch_started = threading.Event()
        dispatch_completed = threading.Event()

        def blocking_session_end(*_args: object) -> None:
            dispatch_started.set()
            release.wait(timeout=5.0)
            dispatch_completed.set()

        app = DeepAgentsApp()
        async with app.run_test() as pilot:
            await pilot.pause()

            with (
                patch(
                    "deepagents_code.hooks._load_hooks",
                    return_value=[{"command": ["x"]}],
                ),
                patch(
                    "deepagents_code.hooks._dispatch_hook_sync",
                    side_effect=blocking_session_end,
                ),
                patch.object(App, "exit") as super_exit,
            ):
                app.exit()
                pending = app._graceful_exit_task
                assert pending is not None
                # session.end is dispatched off-loop at the start of teardown
                # and is still blocked here.
                await asyncio.wait_for(
                    asyncio.to_thread(dispatch_started.wait, 2.0), timeout=3.0
                )
                super_exit.assert_not_called()

                # Force-quit: the loop-stopping call fires while session.end is
                # still in flight, so in production it would be dropped.
                app.exit()
                super_exit.assert_called_once()
                assert not dispatch_completed.is_set()

                release.set()
                await asyncio.wait_for(pending, timeout=2.0)

